_DEEP_LAYER_TYPES = (
    Conv2D, BatchNorm2D, Dropout,
    (MaxPool2D, AdaptiveAvgPool2D),
    Flatten, Linear, ReLU, Linear, SoftmaxCrossEntropy,
)
